377	### Task 2.2 ∥ R2: flat PLAIN fixed-width fast path (V1 pages)
378	
379	- Files: `zig-parquet/src/core/column_decoder.zig`
380	- Depends on: Gate 1
381	- Change: add two private functions next to `decodeLevelsForDynamicWithEncoding`:
382	
383	```zig
384	/// Fast path for flat PLAIN INT32/INT64/FLOAT/DOUBLE pages: decodes straight into
385	/// `Value`s with one length check per page. Returns null (caller must use the
386	/// general path) when levels fail to decode or the page is short, so malformed
387	/// pages keep their existing errors and lenient behavior.
388	fn decodeFlatPlainFixed(
389	    allocator: std.mem.Allocator,
390	    physical_type: format.PhysicalType,
391	    value_data: []const u8,
392	    num_values: usize,
393	    max_def_level: u8,
394	    def_level_encoding: format.Encoding,
395	    rep_level_encoding: format.Encoding,
396	) !?DynamicDecodeResult {
397	    const width: usize = switch (physical_type) {
398	        .int32, .float => 4,
399	        .int64, .double => 8,
400	        else => return null,
401	    };
402	    const lv = decodeLevelsForDynamicWithEncoding(allocator, value_data, num_values, max_def_level, 0, def_level_encoding, rep_level_encoding) catch |e| switch (e) {
403	        error.OutOfMemory => return error.OutOfMemory,
404	        else => return null,
405	    };
406	    defer allocator.free(lv.def_mask);
407	
408	    const body = value_data[lv.data_offset..]; // data_offset <= len, checked by the level decoder
409	    const needed = std.math.mul(usize, lv.non_null_count, width) catch std.math.maxInt(usize);
410	    if (body.len < needed) {
411	        if (lv.def_levels) |d| allocator.free(d);
412	        return null;
413	    }
414	
415	    const values = allocator.alloc(Value, num_values) catch |e| {
416	        if (lv.def_levels) |d| allocator.free(d);
417	        return e;
418	    };
419	    switch (physical_type) {
420	        .int32 => fillPlainFixed(i32, values, body, lv.def_mask),
421	        .int64 => fillPlainFixed(i64, values, body, lv.def_mask),
422	        .float => fillPlainFixed(f32, values, body, lv.def_mask),
423	        .double => fillPlainFixed(f64, values, body, lv.def_mask),
424	        else => unreachable, // filtered by the width switch above
425	    }
426	    return .{ .values = values, .def_levels = lv.def_levels, .rep_levels = null };
427	}
428	
429	fn fillPlainFixed(comptime T: type, out: []Value, body: []const u8, def_mask: []const bool) void {
430	    const Bits = if (@sizeOf(T) == 4) u32 else u64;
431	    var off: usize = 0;
432	    for (def_mask, out) |present, *v| {
433	        if (!present) {
434	            v.* = .{ .null_val = {} };
435	            continue;
436	        }
437	        // In bounds: caller checked body.len >= non_null_count * @sizeOf(T).
438	        const x: T = @bitCast(std.mem.readInt(Bits, body[off..][0..@sizeOf(T)], .little));
439	        v.* = switch (T) {
440	            i32 => .{ .int32_val = x },
441	            i64 => .{ .int64_val = x },
442	            f32 => .{ .float_val = x },
443	            f64 => .{ .double_val = x },
444	            else => @compileError("fillPlainFixed: unsupported " ++ @typeName(T)),
445	        };
446	        off += @sizeOf(T);
447	    }
448	}
449	```
